MultiLanguageSpellData['de'][339957] = {name = "Hand von Hrestimorak", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der niederträchtige Verrat von Hrestimorak, der ihn auf Kosten seines Volkes an die Macht brachte, ist fast schon legendär. Als ihm die Verdammnis im Schlund drohte, versuchte er, den Kerkermeister zu stürzen... Ein törichtes Unterfangen, das ihm eine Ewigkeit voller Qualen einbrachte.\"\nErfolg:\nRuhm des herrschenden Schlachtzüglers\nZone:\nSanktum der Herrschaft"}
MultiLanguageSpellData['de'][339958] = {name = "Hungernde Leere", additional_info = "60 Meter Reichweite\nSofort\n[q]Öffnet einen Riss in das Nichts, der alle Gegner in der Nähe anzieht und alle 1 Sek. Schattenschaden verursacht. Im Epizentrum des Risses werden Gegner mit ' Einhüllende Leere ' belegt, was den durch ' Hungernde Leere ' verursachten Schaden um 1000% erhöht."}
MultiLanguageSpellData['de'][339959] = {name = "Anspringen", additional_info = "30 Meter Reichweite\n{Sofort} {30 sek. Abklingzeit}\n[q]Springt zu einem Zielort innerhalb von 30 Metern, betäubt alle Gegner in der Nähe und fügt ihnen Schaden zu."}
MultiLanguageSpellData['de'][339960] = {name = "Dominantes Brüllen", additional_info = "Wirken in 1.5 sek.\n[q]Stößt ein wildes Gebrüll aus, das Gegner innerhalb von 40 Metern anlockt. Funktioniert nicht bei Zielen, die nicht aus den Schattenlanden stammen."}
