MultiLanguageSpellData['de'][340078] = {name = "[q5]Winzige vergiftete Klinge", additional_info = "Runenschnitzmacht\n[q2]'Tückische Klinge' verursacht 500% mehr Schaden und kostet keine Energie mehr.\n[q]Runenschnitzen: Taille, Füße\n[q]Quelle: Quest: Die Große Schatzkammer\n[q]Benötigt: Schurke"}
MultiLanguageSpellData['de'][340079] = {name = "[q5]Essenz des Blutzahns", additional_info = "Runenschnitzmacht\n[q2]Eure Combopunkte erzeugenden Fähigkeiten haben eine Chance, das Ziel mit 'Blutzahn' zu infizieren, was ihm 0 Blutungsschaden im Verlauf von 6 Sek. zufügt und Euch um 50% des verursachten Schadens heilt.\n(Procchance: 30%, 200ms Abklingzeit)\n[q]Runenschnitzen: Kopf, Schulter, Finger\n[q]Quelle: Schlachtzugbeute: Generäle der Steinlegion\n[q]Benötigt: Schurke"}
MultiLanguageSpellData['de'][340080] = {name = "[q5]Belebender Schattenstaub", additional_info = "Runenschnitzmacht\n[q2]'Verschwinden' verringert die verbleibende Abklingzeit Eurer anderen Fähigkeiten um 20 Sek.\n[q]Runenschnitzen: Hals, Brust\n[q]Quelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n[q]Benötigt: Schurke"}
MultiLanguageSpellData['de'][340081] = {name = "[q5]Bestechender Halunke", additional_info = "Runenschnitzmacht\n[q2]'Vergiften' erhöht zusätzlich die kritische Trefferchance Eurer Gifte um 15% und deren kritische Treffer erzeugen 1 Energie.\n[q]Runenschnitzen: Füße, Rücken\n[q]Quelle: Schlachtzugbeute: Der Rat des Blutes\n[q]Benötigt: Schurke (Meucheln)"}
MultiLanguageSpellData['de'][340082] = {name = "[q5]Verdammnisklinge", additional_info = "Runenschnitzmacht\n[q2]'Verstümmeln' verursacht zusätzlich 45% Blutungsschaden im Verlauf von 8 Sek.\n\n Der Schaden von 'Vergiften' wird pro beim Ziel aktiven Blutungseffekt um 5% erhöht.\n[q]Runenschnitzen: Schulter, Hände, Rücken\n[q]Quelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\n[q]Benötigt: Schurke (Meucheln)"}
MultiLanguageSpellData['de'][340083] = {name = "[q5]Insigne von Zoldyck", additional_info = "Runenschnitzmacht\n[q2]Eure Gifte und Blutungseffekte fügen Zielen mit weniger als 30% Gesundheit 30% mehr Schaden zu.\n[q]Runenschnitzen: Beine, Füße\n[q]Quelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\n[q]Benötigt: Schurke (Meucheln)"}
MultiLanguageSpellData['de'][340084] = {name = "[q5]Notlösung des Dämmergängers", additional_info = "Runenschnitzmacht\n[q2]Die verbleibende Abklingzeit von 'Todesmal' wird pro 30 verbrauchter Energie um 1 Sek. verringert.\n[q]Runenschnitzen: Brust, Finger\n[q]Quelle: Dungeonbeute: Nebelruferin\n[q]Benötigt: Schurke (Meucheln)"}
MultiLanguageSpellData['de'][340085] = {name = "[q5]Grünhauts Ruten", additional_info = "Runenschnitzmacht\n[q2]'Zwischen die Augen' hat eine Chance von 20% pro Combopunkt, den Schaden Eures nächsten Einsatzes von 'Pistolenschuss' um 300% zu erhöhen.\n[q]Runenschnitzen: Kopf, Taille\n[q]Quelle: Schlachtzugbeute: Schlickfaust\n[q]Benötigt: Schurke (Gesetzlosigkeit)"}
MultiLanguageSpellData['de'][340086] = {name = "[q5]Argliststalisman", additional_info = "Runenschnitzmacht\n[q2]Macht Euch den natürlichen Verlauf eines Kampfes zunutze, sodass Eure Einsätze von 'Finsterer Stoß' im Laufe der Zeit Euren verursachten Schaden um bis zu 15% erhöhen. Dieses Maximum hält 12 Sek. lang an. Anschließend beginnt der Kreislauf von vorn.\n[q]Runenschnitzen: Hals, Handgelenk\n[q]Quelle: Weltbossbeute: Mortanis\n[q]Benötigt: Schurke (Gesetzlosigkeit)"}
MultiLanguageSpellData['de'][340087] = {name = "[q5]Schnelligkeit", additional_info = "Runenschnitzmacht\n[q2]'Adrenalinrausch' erhöht Euren Schaden um 8%, und während 'Zerhäckseln' aktiv ist, habt Ihr eine Chance, 3 Sek. lang den Effekt 'Adrenalinrausch' zu erhalten.\n[q]Runenschnitzen: Schulter, Finger\n[q]Quelle: Dungeonbeute: Ventunax\n[q]Benötigt: Schurke (Gesetzlosigkeit)"}
