MultiLanguageSpellData['de'][342665] = {name = "Todessplitter", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Todessplitter verursachen 20 Schattenschaden und betäuben Spielercharaktere innerhalb von 3 Metern um ihre Position für 5 Sek."}
MultiLanguageSpellData['de'][342666] = {name = "Bernsteinardenmotte", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Das leuchtende Orange der Bernsteinardenmotte signalisiert Raubtieren, dass es gefährlich wäre, sie zu verspeisen. Eine dieser Kreaturen zu verzehren, würde ein Raubtier für mehrere Jahre in einen traumlosen Schlaf versetzen.\"\nBeute:\nVorräte der Wilden Jagd\nZone:\nArdenwald"}
MultiLanguageSpellData['de'][342667] = {name = "Schillernder Schwirrling", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese minzgrünen Motten sind sehr freundlich. Sie mögen es besonders, wenn man ihnen den Kopfflaum kräftig durchbürstet. Außerdem mögen sie Musik und Poesie.\"\nVerkäufer:\nCortinarius\nZone:\nArdenwald"}
MultiLanguageSpellData['de'][342668] = {name = "Wüstenschwingenjäger", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Wüstenschwingenjäger wurden im Dienste der großen Vorhersehung erschaffen, um die weiten Himmel der vergessenen Reiche der Schattenlande zu erfüllen.\"\nBeruf:\nProtoformsynthese"}
