MultiLanguageSpellData['de'][344574] = {name = "Knolliger Nekrorochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Nekrorochen von Maldraxxus tummeln sich bevorzugt in der Nähe der riesigen, verfaulenden Pilze der Region.\"\nBeute:\nSchleimiges Nekrorochenei"}
MultiLanguageSpellData['de'][344575] = {name = "Verseuchter Nekrorochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Wenn ein Nekrorochen ausschlüpft, fliegen Sporen in alle Richtungen.\"\nBeute:\nSchleimiges Nekrorochenei"}
MultiLanguageSpellData['de'][344576] = {name = "Befallener Nekrorochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Nekrorochen legen ihre Eier als kleine Pakete in die Lamellen und Winkel verrottender Pilzfruchtkörper.\"\nBeute:\nSchleimiges Nekrorochenei"}
MultiLanguageSpellData['de'][344577] = {name = "Gebundener Schemenhund", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Dieser Schemenhund wurde durch die Entschlüsselung und Durchführung mächtiger Runenmagie erschaffen und ist an seinen Schöpfer gebunden.\"\nQuest:\nWilder Schemenhund\nZone:\nDer Schlund"}
MultiLanguageSpellData['de'][344578] = {name = "Korridorkriecher", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die loyalen Hunde des Kerkermeisters schleichen durch die Korridore auf der Suche nach dem Geruch von Seelen.\"\nErfolg:\nDie Gewundenen Korridore: Ebene 8\nKategorie:\nTorghast"}
