MultiLanguageSpellData['de'][352498] = {name = "Gemeinsam besser", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn Ihr Euch während des Kampfs einem Gruppen- oder Schlachtzugsmitglied auf 3 Meter nähert, werdet Ihr beide inspiriert, was Euer beider Meisterschaft für 1 Min. um 109 erhöht.\n\n Spielercharaktere können nur jeweils von einem solchen Effekt betroffen sein."}
MultiLanguageSpellData['de'][352500] = {name = "Kevins Schlammling", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn Ihr Eure Nekrolordklassenfähigkeit aktiviert, wird Kevins Schlammling beschworen und kämpft (20 * 1 ) Sek. lang an Eurer Seite. Seine Angriffe lassen Gegner 6% mehr Schaden durch Euch erleiden und er gewährt Euren Verbündeten regelmäßig einen Absorptionsschild in Höhe von [Max(Zaubermacht, Angriffskraft) * .1 * (1 + Vielseitigkeit)] Schaden."}
MultiLanguageSpellData['de'][352501] = {name = "Angekündigter Schuss", additional_info = "[q0]Seelenbandefähigkeit\n[q]Wenn Ihr kritische Treffer erzielt, wird Eure Bewegungsgeschwindigkeit 5 Sek. lang um 20% erhöht.\n\n Kann nur einmal alle 10 Sek. auftreten.\n(10s Abklingzeit)"}
MultiLanguageSpellData['de'][352502] = {name = "Ermutigung der Überlebenden", additional_info = "[q0]Seelenbandefähigkeit\n[q]Wenn Eure Gesundheit unter 50% fällt, erhaltet Ihr im Verlauf von 10 Sek. 20% Eurer Gesundheit zurück und erhaltet dabei 10% mehr Heilung durch andere Zauber und Fähigkeiten.\n\n Kann nur einmal alle 60 Sek. auftreten."}
MultiLanguageSpellData['de'][352503] = {name = "Verbundene Herzen", additional_info = "[q0]Seelenbandefähigkeit\n[q]Wenn Ihr durch 'Hainkräftigung' einen Stapel von 'Umgeleitete Anima' erhaltet, werden bis zu 5 Verbündete in der Nähe um 2% ihrer Gesundheit geheilt, bis zu maximal 2000 Gesundheit. Wenn unter diesen Verbündeten Mitglieder anderer Pakte sind, wird der Effekt von 'Umgeleitete Anima' auf Meisterschaft und maximale Gesundheit für 5 Sek. um 50% erhöht."}
