MultiLanguageSpellData['de'][353872] = {name = "Grabschwinge von Sündensturz", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Da die Anima in Sündensturz wieder fließt, konnte die Steinhauerin diese Steingeborenen damit anreichern, was sie zu wertvollen Verbündeten in den kommenden Schlachten macht.\"\nPakt:\nVenthyr\nZone:\nRevendreth"}
MultiLanguageSpellData['de'][353873] = {name = "Bleiche Grabschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Grabschwingen kennen keine Furcht und sind nahezu unverwundbar, was für einen Angriff auf den Schlund perfekt ist.\"\nPakt:\nVenthyr\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive"}
MultiLanguageSpellData['de'][353875] = {name = "Elysischer Aquilon", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Da die Anima wieder in die Ewige Schmiede in der Bastion fließt, konnte die Produktion des Aquilonzenturios wieder aufgenommen werden.\"\nPakt:\nKyrianer\nZone:\nBastion"}
MultiLanguageSpellData['de'][353877] = {name = "Aquilon der Verschmähten", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese mächtigen Zenturionen wurden von den Verschmähten ursprünglich mithilfe gestohlener Baupläne erschaffen, doch heute machen sie sich in den gesamten Schattenlanden einen Namen.\"\nPakt:\nKyrianer\nBeute von:\nWilder Weltenknacker\nZone:\nKorthia"}
MultiLanguageSpellData['de'][353878] = {name = "Werfen", additional_info = "40 Meter Reichweite\n{Wirken in} {2 sek. 6 sek. Abklingzeit}\n[q]Wirft einen Faespeer auf einen schlundgebundenen Herold und zerrt ihn zu Euch herunter."}
MultiLanguageSpellData['de'][353880] = {name = "Aquilon des Aszendenten", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der Aquilon kann blitzschnell Aspiranten, Provosten und sogar Aufgestiegene von Ort zu Ort transportieren. Hey, manchmal werden einem eben die Flügel müde.\"\nPakt:\nKyrianer\nVerkäufer:\nAdjutant Galos\nZone:\nBastion\nKosten:\n7500"}
MultiLanguageSpellData['de'][353881] = {name = "Werfen", additional_info = "100 Meter Reichweite\n{Sofort} {6 sek. Abklingzeit}\n[q]Wirft einen Faespeer auf einen schlundgebundenen Herold und zerrt ihn zu Euch herunter."}
MultiLanguageSpellData['de'][353882] = {name = "[q5]Rasende Übertragung", additional_info = "Runenschnitzmacht\nSofort\n[q2]Die durch 'Recht des Todes' erhaltene Stärke ist um 3% erhöht und hält 2 Sek. länger an. Während Ihr Euch im Effektbereich von 'Recht des Todes' aufhaltet, ist Eure Runenmachterzeugung um 20% erhöht.\n[q]Runenschnitzen: Brust, Taille\n[q]Quelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\n[q]Benötigt: Todesritter"}
MultiLanguageSpellData['de'][353883] = {name = "Maldraxxische Leichenfliege", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Leichenfliegen waren einst in ganz Maldraxxus zu finden, aber viele starben aufgrund des Mangels an Anima. Da die Anima wieder fließt, schwärmen sie jetzt aus.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus"}
MultiLanguageSpellData['de'][353884] = {name = "Majestätische Leichenfliege", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Nur die Truppen von Maldraxxus würden eine Leichenfliege als \"majestätisch\" bezeichnen.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n7500"}
MultiLanguageSpellData['de'][353885] = {name = "Schlachtfeldschwärmer", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Leichenfliegen werden von Leichengeruch stark angezogen und suchen ein aktives Schlachtfeld heim, sobald der erste Kämpfer fällt.\"\nPakt:\nNekrolords\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive"}
