MultiLanguageSpellData['de'][353935] = {name = "Schattendolch", additional_info = "Unbegrenzte Reichweite\nWirken in 1.5 sek.\n[q]Sylvanas verschießt einen schreckenserfüllten Pfeil auf einen Spielercharakter, der 47924 Schattenschaden verursacht und allen anderen Spielercharakteren zusätzlich bis zu 111823 Schattenschaden zufügt. Der Schaden nimmt dabei mit zunehmender Entfernung zum Einschlagsort ab."}
MultiLanguageSpellData['de'][353936] = {name = "Donnernder Fokustee", additional_info = "[q]'Donnerfokustee' kann zusätzlich den Rückstoßeffekt von 'Knisternder Jadeblitz' sofort auslösen oder dafür sorgen, dass 'Rollen' und 'Chitorpedo' beim Einsatz eine Aufladung zurückerstatten und Euch um (240% der Angriffskraft) Gesundheit heilen."}
