MultiLanguageSpellData['de'][354351] = {name = "Sanktumdämmerstreitross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Nur die mächtigsten Leutnants des Kerkermeisters erhalten diese Rösser, um durch die Hallen des Turms zu reiten.\"\nBeute von:\nDie Neun\nZone:\nSanktum der Herrschaft"}
MultiLanguageSpellData['de'][354352] = {name = "Seelengebundenes Dämmerstreitross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ve'nari hat viele Methoden, im Schlund herumzuschleichen und die Pläne des Kerkermeisters zu durchkreuzen, darunter auch das Binden seiner Diener.\"\nBeute von:\nGeheimnisvolles Geschenk von Ve'nari\nZone:\nDer Schlund"}
MultiLanguageSpellData['de'][354353] = {name = "Gefallenes Streitross", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Schreie des Streitrosses hallen durch den Schlund, während es seinen endlosen Ritt durch das Land fortsetzt, immer auf der Suche nach einem Ausweg aus den endlosen Qualen, denen es ausgesetzt ist.\"\nBeute von:\nZone:\nDer Schlund"}
MultiLanguageSpellData['de'][354354] = {name = "Hand von Nilganihmaht", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Von allen Riesen, die es wagten, dem Kerkermeister zu trotzen, war Nilganihmaht der arroganteste. Für sein Vergehen wurde die abgetrennte Hand des Riesen in einem Schleier der Qualen verborgen und die Ringe, die sie zurückbringen könnten, wurden über den ganzen Schlund verstreut.\"\nZone:\nDer Schlund"}
MultiLanguageSpellData['de'][354355] = {name = "Hand von Salaranga", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Salaranga war die gerissenste ihrer Art und versteckte sich im Bestienlabyrinth. Sie griff den Verbannten mit einer Horde aus verbündeten Bestien an, auch wenn dies letztendlich keinen Unterschied machte.\"\nErfolg:\nDie Ketten durchbrechen\nZone:\nKorthia und der Schlund"}
MultiLanguageSpellData['de'][354356] = {name = "Bernsteinsplitterfell", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die leuchtenden Farben der korthianischen Wildtiere deuten darauf hin, dass ihnen entweder nur wenige Raubtiere auflauern oder sie sich zu wehren wissen.\"\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nVorstoß des Todes - Respektvoll\nKosten:\n5.000"}
MultiLanguageSpellData['de'][354357] = {name = "Blutrotes Splitterfell", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Als Korthia in den Schlund gezogen wurde, überlebten nur wenige besonders widerstandsfähige Arten.\"\nBeute von:\nMalbog\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354358] = {name = "Finsterpranke", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Finsterpranke ist ein älteres Splitterfell und trat den Korthianern zumeist recht zahm und freundlich gegenüber. Man glaubte, er sei in der Katastrophe verloren gegangen.\"\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354359] = {name = "Grimmige Klingenschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Klingenschwingen halten sich im Allgemeinen von anderen korthianischen Spezies fern, aber mit etwas Zeit und Geduld lassen auch sie sich zähmen.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354360] = {name = "Granatklingenschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Korthia war einst für seine leuchtend roten Blumen bekannt. Von mehreren Wildtieren weiß man, dass sie diese verzehrten oder sich darin wälzten, um eine leuchtend rote Färbung anzunehmen.\"\nBeute von:\nReliwik der Trotzige\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354361] = {name = "Dämmerlichtklingenschwinge", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Klingenschwingen sind in ganz Korthia beheimatet. Sie bauen ihre Nester auf hohen Hügeln und in Bäumen.\"\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354362] = {name = "Wandernde Ardenhirschkuh", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese neugierige und wissbegierige Hirschkuh will ihren Besitzer nicht beunruhigen, aber sie lässt sich eben leicht ablenken. Besonders bei all den neuen Dingen, die es in Korthia zu sehen gibt.\"\nZone:\nKorthia"}
MultiLanguageSpellData['de'][354363] = {name = "Finsteres Omen", additional_info = "Sofort\n[q]Schicksalsschreiber Roh-Kalo bindet mehrere Spielercharaktere an Runen auf dem Webstuhl der Schicksale.\n\n Falls ein gebundener Spielercharakter nach 9 Sek. seine zugewiesene Rune berührt, fügt der Schicksalsschreiber allen Spielercharakteren in der Rune 19968 Schattenschaden zu.\n\n Wenn eine Rune abläuft, ohne dass sich der daran gebundene Spielercharakter in ihr befindet, fügt der Schicksalsschreiber allen Spielercharakteren 107829 Schattenschaden zu."}
