MultiLanguageSpellData['de'][354374] = {name = "Bann der Banshee", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Sylvanas belegt Ziele mit einem unersättlichen Leiden, das pro Sekunde 1 Schattenschaden verursacht. Dieser Effekt ist stapelbar. Bei Entfernung verschmilzt dieser Effekt zu einer Schattenlache auf dem Boden. Wenn ein Spielercharakter die Lache berührt, erhält er ' Bann der Banshee ' und verbraucht die Lache."}
MultiLanguageSpellData['de'][354376] = {name = "Wütende Tritte", additional_info = "{Sofort} {20 sek. Abklingzeit}\n[q]Verschwindet vor Gegnern, indem Ihr an Eurer aktuellen Position eine Staubwolke erschafft, die verbündete Einheiten für 5 Sek. verbirgt.\n\n Tubbins kann innerhalb der Staubwolke Tee servieren."}
