MultiLanguageSpellData['de'][359364] = {name = "Bronzeflügelvespid", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Bronzeflügelvespiden sind ein Ergebnis des Versuchs, eine Vespidenkönigin ohne weitere Mitglieder eines neuen Schwarms zu synthetisieren. Obwohl bisher noch kein Sterblicher herausgefunden hat, wie man einen Stock synthetisiert, stellen die Bronzeflügel selbst in ihrem aktuellen Zustand verlässliche Reittiere dar.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359366] = {name = "Summ", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Summ summ summ, summ summ! Summ summ summ summ summ. Summ summ summ, summ summ summ.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359367] = {name = "Geschmiedeter Tückenflügler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Es gibt kaum etwas, das einen das Leben so sehr spüren lässt wie ein Ritt durch das Reich des Todes auf dem Rücken eines Wesens, das einen hasst.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359372] = {name = "Schlundadaptierter Raptora", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Seit dem Übergriff des Kerkermeisters sind neue Raptoras durch Zereth Mortis synthetisiert worden, die dem verderbenden Einfluss des Schlunds widerstehen können.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359373] = {name = "Raptorasturzflieger", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Der Raptorasturzflieger ist eine der grausamsten Ausprägungen dieser Art, perfekt an seine ökologische Nische angepasst. Die Sturzflieger, die heutzutage synthetisiert werden, benötigen keine weitere Anpassungen und sind identisch mit denen, die in der Vergangenheit erschaffen wurden.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359374] = {name = "Negationsschutz", additional_info = "30 Meter Reichweite\nWirken in 1.5 sek.\n[q]Hüllt das Ziel in einen Schild, der Angreifern 10 Sek. lang kosmischen Schaden zufügt.\n(250ms Abklingzeit)"}
MultiLanguageSpellData['de'][359375] = {name = "Negationsschutz", additional_info = "50 Meter Reichweite\nSofort\n[q]Verursacht kosmischen Schaden."}
MultiLanguageSpellData['de'][359376] = {name = "Bronzener Helicid", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Einige Heliciden von Zereth Mortis haben von Natur aus seltsam metallische Schneckenhäuser. Sie sind üblicherweise bronzefarben, und ihr Metall unterscheidet sich nicht von dem, mit dem sogar Anfänger unter den Minenarbeitern umgehen können, mit der Einschränkung, dass die Konstruktion dieser Kreatur die Fähigkeiten von Anfängern mehr als überfordern würde.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359377] = {name = "Gescheiterter Flitzopodenprototyp", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Kreatur ist nicht von den Ersten entworfen worden, sondern stattdessen von einem unbekannten Wesen in dem Versuch, einen sehr schnellen Läufer zu kreieren. Es blieb bei dem Versuch, da dieses Reittier doch sehr langsam ist.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359378] = {name = "Scharlachroter Helicid", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die ungewöhnliche rötliche Färbung dieses Heliciden ist eindeutig beabsichtigt, und der einzige andere Unterschied zwischen diesem und anderen Heliciden ist das ungewöhnliche Fehlen von Schleim.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359379] = {name = "Schimmernder Aurelid", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Obschon er einst geschaffen wurde, das Mausoleum der Ersten zu verteidigen, folgt er jetzt nach der Erfüllung seiner Primärfunktion gehorsam Euren Befehlen.\"\nErfolg:\nRuhm des Mausoleumsschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge"}
MultiLanguageSpellData['de'][359380] = {name = "Tiefenpirscher", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Ein paar dieser Quallen wurden in Zereth Mortis gewildert und sind über Bord gegangen, als das Schiff der Wilderer sank. Sie haben in den Tiefen des Großen Meeres ein neues Zuhause gefunden.\"\nHandelsposten"}
MultiLanguageSpellData['de'][359381] = {name = "Kryptischer Aurelid", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Die Chiffren der Ersten entziehen sich dem Verständnis der Sterblichen. Ein seltsamer Effekt dieser Sprache ist, dass sich einige Aureliden aus unbekannten Gründen zu jenen Sterblichen hingezogen fühlen, die danach streben, das Mysterium zu ergründen.\"\nErfolg:\nVon A bis Zereth\nKategorie:\nSchattenlande"}
MultiLanguageSpellData['de'][359383] = {name = "Sofortige Auslöschung", additional_info = nil}
MultiLanguageSpellData['de'][359384] = {name = "Brons Aufruf zum Handeln", additional_info = "Sofort\n[q]Nach dem Einsatz von 75 Schadens- oder Heilzaubern und -fähigkeiten beschwört Euer nächster Zauber oder Eure nächste Fähigkeit Bron. Bron stößt Gegner bei seiner Ankunft zurück und greift 30 Sek. lang Eure Ziele an oder heilt sie."}
MultiLanguageSpellData['de'][359386] = {name = "Schlundgebundene Barriere", additional_info = nil}
MultiLanguageSpellData['de'][359387] = {name = "Winterwinde", additional_info = "Sofort\n[q]Im Schlund oder in Torghast sammeln die Winde jedes Mal, wenn Ihr einen kritischen Treffer erzielt, 13% des Effekts, bis zu einem Höchstwert von 28572 pro kritischem Treffer.\n\n Die Winde werden alle 20 Sek. entfesselt und verursachen Frostschaden in Höhe des insgesamt angesammelten Schadens. Zusätzlich werdet Ihr für 20 Sek. in die Winde gehüllt und absorbiert Schaden in Höhe von 100% des von den Winden verursachten Schadens."}
MultiLanguageSpellData['de'][359395] = {name = "Blutverbindung", additional_info = "Sofort\n[q]Wenn Ihr einem Gegner im Schlund oder in Torghast Schaden zufügt, entsteht eine 'Blutverbindung'.\n\n Die Blutverbindung pulsiert alle 3 Sek., verursacht dabei 102858 Schattenschaden und heilt Euch um 100% des verursachten Schadens. Anstatt überschüssige Heilung bei Euch hervorzurufen, heilt die Blutverbindung stattdessen einen Verbündeten in der Nähe. Maximal 1 Blutverbindung."}
MultiLanguageSpellData['de'][359396] = {name = "Chaosbann", additional_info = "Sofort\nCa. 8 Procs pro Minute\n[q]Im Schlund und in Torghast haben Eure Zauber und Fähigkeiten eine Chance, Eurem Ziel ein Seelenfragment zu entziehen, das Euren Primärwert 30 Sek. lang um 605 erhöht. Bis zu 15-mal stapelbar.\n\n Bei Erreichen von 15 Stapeln entfesselt Ihr 'Chaosbann', was 90686 Schattenschaden verursacht, der auf Gegner in der Nähe aufgeteilt wird, und Euren Primärwert 15 Sek. lang um 18137 erhöht.\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][359397] = {name = "Heulender Blizzard", additional_info = nil}
MultiLanguageSpellData['de'][359398] = {name = "Sternenregen", additional_info = nil}
MultiLanguageSpellData['de'][359399] = {name = "Sternenregen", additional_info = "200 Meter Reichweite\nSofort\n[q]Ruft Wellen fallender Sterne auf Gegner innerhalb von 40 Metern herab, die Gegnern im Verlauf von 8 Sek. [9 * (22.4% der Zaubermacht)] Astralschaden zufügen. Mehrfache Anwendungen dieser Fähigkeit können sich überschneiden. [ Ätherischer Zunder : Verlängert die Dauer aktiver Effekte von 'Mondfeuer' und 'Sonnenfeuer' um 3 Sek ]"}
MultiLanguageSpellData['de'][359400] = {name = "Stachelige Bälle", additional_info = "Sofort\n[q]Der Leidensschmied lässt stachelige Bälle über den Boden der Kammer rollen, die Spielercharakteren in ihrer Bahn 400 körperlichen Schaden zufügen und sie für 8 Sek. betäuben."}
MultiLanguageSpellData['de'][359401] = {name = "Genesiskrabbler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Jene Erleuchteten, die Tarachniden beobachtet haben, glauben, dass diese Art zu den ersten Wesen gehörte, die durch die Länder von Zereth Mortis streiften.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359402] = {name = "Tarachnidenkriecher", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Tarachniden hausen in den finstersten Ecken von Zereth Mortis und verlassen sie nur, um zu jagen (oder um manchmal einen Reiter auf ihrem Rücken zu tragen).\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359403] = {name = "Unergründlicher Krabbler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Tarachniden bewegen sich mit einer Absicht, die niemand nachvollziehen kann, und scheinen nur einem höheren Ruf zu folgen. Was auch immer sich dahinter verbergen mag, es scheint regelmäßige Hilfe für Sterbliche zu beinhalten, die ein Reittier benötigen. Für den Moment zumindest.\"\nBeruf:\nProtoformsynthese"}
MultiLanguageSpellData['de'][359407] = {name = "Verlustverzerrter Todeswandler", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese raue, wirbelnde Energie ist in kohäsiver Form gebunden und unterwirft sich nur dem Willen derjenigen, die stark und entschlossen genug sind, sie zu binden.\"\nErfolg:\nSchlüsselsteinmeister von Shadowlands: Saison 3\nKategorie:\nDungeons"}
MultiLanguageSpellData['de'][359408] = {name = "Göttlicher Kuss von Ohn'ahra", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei."}
MultiLanguageSpellData['de'][359409] = {name = "Ottuk des Iskaarahändlers", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Es gibt keine Garantie beim Kauf eines Ottuks von Tattukiaka. Immerhin sind sie niedlich.\"\nVerkäufer:\nTattukiaka\nZone:\nAzurblaues Gebirge\nKosten:\n1\n1"}
