MultiLanguageSpellData['de'][360006] = {name = "Wolke der Fäulnis", additional_info = "Wirken in 2.5 sek.\n[q]Mal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 1 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\n Wenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über und die Intensität wird zurückgesetzt.\n\n Bei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt."}
MultiLanguageSpellData['de'][360007] = {name = "[q3]Magisch regulierter Automakern", additional_info = "Wirken in 1.5 sek.\nTools: Runenverzierte Verzauberkunstrute\nReagenzien:\nEwiger Kristall (5), Progeniumerz , Unsterblichkeitssplitter (5)\nVerkäufer:\nOlea Manu\nZone:\nZereth Mortis\nKosten:\n25\n\n[q3]Magisch regulierter Automakern\nOptionales Handwerksmaterial\n\n[q2]Gewährt die folgende Eigenschaft: Chance durch Fähigkeiten, in Zielnähe Automakern zu erzeugen, der Schaden und Heilung verursacht.\n[q]Benutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör."}
MultiLanguageSpellData['de'][360008] = {name = "Wolke der Fäulnis", additional_info = "150 Meter Reichweite\nSofort\n[q]Mal'Ganis umgibt das Ziel mit einer Insektenwolke, die ihm alle 0.5 Sek. 7310 Seuchenschaden zufügt. Die Intensität nimmt mit der Zeit zu.\n\n Wenn sich das Ziel einem anderen Spielercharakter bis auf 5 Meter nähert, springen die Insekten auf diesen über, desorientieren ihn für 1 Sek. und die Intensität wird zurückgesetzt.\n\n Bei Entfernung wird das Ziel mit ' Beißende Wunden ' belegt."}
