MultiLanguageSpellData['de'][364719] = {name = "Pflichtgebundener Hammer", additional_info = "[q]Vergeltung\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Urteil des Templers' löst automatisch 'Göttlicher Sturm' aus.\n\nHeilig\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Licht der Morgendämmerung' aus.\n\nSchutz\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Schild der Rechtschaffenen' aus."}
MultiLanguageSpellData['de'][364722] = {name = "Strahlende Glut", additional_info = "[q]Erhöht die Dauer von 'Ascheweihung' um 50%. Wenn Ihr den Effekt vorzeitig aufhebt, wird die Abklingzeit abhängig von der verbleibenden Dauer um bis zu 50% verringert."}
MultiLanguageSpellData['de'][364724] = {name = "Göttliche Resonanz", additional_info = "30 Meter Reichweite\n[q]Heilig\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Heiliger Schock' ein. Dieser Effekt hält 15 Sek. lang an.\n\nVergeltung\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Richturteil' ein. Dieser Effekt hält 15 Sek. lang an.\n\nSchutz\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. 'Schild des Rächers' ein. Dieser Effekt hält 15 Sek. lang an."}
