MultiLanguageSpellData['de'][364733] = {name = "Tobender Vortex der Vesperglocke", additional_info = "[q]Wenn 3 Aufladungen des Vespertotems verbraucht sind, strahlt das Vespertotem (300% der Zaubermacht) Arkanschaden und (110% der Zaubermacht) Heilung innerhalb von 15 Metern aus."}
MultiLanguageSpellData['de'][364734] = {name = "Elementarverbunden", additional_info = "[q]Auf bis zu 5 verbündete Ziele, die mit 'Kettenernte' geheilt wurden, wird 'Springflut' gewirkt. Auf bis zu 5 gegnerische Ziele, denen mit 'Kettenernte' Schaden zugefügt wurde, wird 'Flammenschock' gewirkt. Kritische Treffer mit 'Flammenschock' verringern die Abklingzeit von 'Kettenernte' um 1.0 Sek."}
MultiLanguageSpellData['de'][364735] = {name = "Samen des ungezügelten Wachsens", additional_info = "[q]Jeder Impuls des Schadenseffekts von 'Faetransfusion' verringert die Abklingzeit von 'Wildgeist' um 9.0 Sek. und erhöht Eure kritische Trefferchance für 15 Sek. um 4%."}
MultiLanguageSpellData['de'][364736] = {name = "Zersplitterte Elemente", additional_info = "[q]Jeder zusätzliche Einsatz von 'Blitzschlag' , der von 'Urzeitliche Welle' erzeugt wird, erhöht Euer Tempo 12 Sek. lang um 10%."}
MultiLanguageSpellData['de'][364737] = {name = "Pflanzlich induzierte Raserei", additional_info = nil}
MultiLanguageSpellData['de'][364738] = {name = "[q5]Einigkeit", additional_info = "Runenschnitzmacht\n[q2]Gewährt einen legendären Effekt Eures auserwählten Pakts.\n[q]Runenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\n[q]Quelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n[q]Benötigt: Schamane"}
MultiLanguageSpellData['de'][364739] = {name = "Pakt der Seelenpirscher", additional_info = "[q]Wenn Euer 'Resonierender Pfeil' einem Ziel Schaden zufügt, wird die kritische Trefferchance Eurer Gruppe für 10 Sek. um 10% erhöht."}
MultiLanguageSpellData['de'][364740] = {name = "Beutel mit Klingenbruchstücken", additional_info = "[q]Durch 'Schinderschuss' ausgelöste Bonuseinsätze von 'Tödlicher Schuss' lassen 6 Ziele innerhalb von 12 Metern bluten, was ihnen 60% des von 'Tödlicher Schuss' verursachten Schadens im Verlauf von 6 Sek. zufügt."}
MultiLanguageSpellData['de'][364741] = {name = "Tasche mit Munition", additional_info = "[q]Bis zu 2 der von Eurem 'Todeschakram' getroffenen Ziele werden zusätzlich von 'Explosivschuss' getroffen."}
MultiLanguageSpellData['de'][364742] = {name = "Fragmente des Ältestengeweihs", additional_info = "[q]Wenn 'Wilde Geister' weniger als 5 Ziele trifft, besteht eine Chance von 100%, dass der Schaden von 'Wilde Geister' erneut verursacht wird."}
MultiLanguageSpellData['de'][364743] = {name = "[q5]Einigkeit", additional_info = "Runenschnitzmacht\n[q2]Gewährt einen legendären Effekt Eures auserwählten Pakts.\n[q]Runenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\n[q]Quelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n[q]Benötigt: Jäger"}
MultiLanguageSpellData['de'][364744] = {name = "Bauplanreintegration: Multihuhn", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für das Multihuhn und ermöglicht es Euch, es mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364745] = {name = "Bauplanreintegration: Aggressiver Puttrid", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für den aggressiven Puttriden und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364746] = {name = "Bauplanreintegration: Stabilisierter Geomentar", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für den stabilisierten Geomentar und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364747] = {name = "Bauplanreintegration: Omnipotenzialkern", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für den Omnipotenzialkern und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364748] = {name = "Endgültiges Urteil", additional_info = "[q]Wenn ein Gegner mit 'Fesseln der Unwürdigen' belegt wird, erhaltet Ihr sofort eine Rune und Euer Schaden wird um 4% erhöht. Hält 15 Sek. lang an und ist bis zu 20% stapelbar."}
MultiLanguageSpellData['de'][364749] = {name = "Bauplanreintegration: Resonantes Echo", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für das resonante Echo und ermöglicht es Euch, es mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364750] = {name = "Schreckenspirscher rufen", additional_info = "100 Meter Reichweite\nSofort\n[q]Beschwört für 12 Sek. 2 wilden Schreckenspirscher, der das Ziel angreift."}
MultiLanguageSpellData['de'][364751] = {name = "Schreckenspirscher rufen", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Beschwört einen dämonischen Meteor voller Wildwichtel herab, die hervorbrechen, um das Ziel anzugreifen.\n\n Fügt beim Einschlag allen Gegnern innerhalb von 8 Metern um das Ziel bis zu [3 * (55.6876% der Zaubermacht)] Schattenflammenschaden zu [ Hand der Verdammnis : belegt alle getroffenen Ziele mit 'Verdammnis' ] und beschwört, basierend auf den aufgezehrten Seelensplittern, bis zu 3 Wildwichtel."}
MultiLanguageSpellData['de'][364752] = {name = "Unstillbarer Hunger", additional_info = "[q]Wenn 'Schwärmender Nebel' endet, fügt die Fähigkeit 5 Gegnern in der Nähe (86.42% der Angriffskraft) Schattenschaden zu und heilt Euch um 25% des verursachten Schadens. Der Schaden erhöht sich pro 1 Runenmacht, die Ihr verbraucht habt, während 'Schwärmender Nebel' aktiv war, um 2%."}
MultiLanguageSpellData['de'][364753] = {name = "Bauplanreintegration: Protoprickler", additional_info = "Sofort\n[q]Gewährt der Protoformschmiede den Bauplan für den Protoprickler und ermöglicht es Euch, ihn mittels Protoformsynthese herzustellen."}
MultiLanguageSpellData['de'][364754] = {name = "Raserei der Monstrosität", additional_info = "[q]Die Dauer von 'Monströse Gliedmaße' ist um 4 Sek. erhöht und die Fähigkeit gewährt [ Blut : 'Knochenschild' / Frost : 'Raureif' / Unheilig : 'Runenverderbnis' ] mit 2 Sek. schnellerer Frequenz. Zusätzlich erleiden Gegner, nachdem sie das erste Mal Schaden durch 'Monströse Gliedmaße' erlitten haben, 12 Sek. lang 20% mehr Schaden durch Euch."}
MultiLanguageSpellData['de'][364755] = {name = "Rasende Übertragung", additional_info = "[q]Die durch 'Recht des Todes' erhaltene Stärke ist um 3% erhöht und hält 2 Sek. länger an. Während Ihr Euch im Effektbereich von 'Recht des Todes' aufhaltet, ist Eure Runenmachterzeugung um 20% erhöht."}
