MultiLanguageSpellData['de'][364851] = {name = "Die Dämmerung wird kommen", additional_info = "Sofort\n[q]Für jedes von 'Licht der Morgendämmerung' getroffene Ziel besteht eine Chance von 50%, die verbleibende Abklingzeit von 'Zornige Vergeltung' um 2 Sek. zu verringern."}
MultiLanguageSpellData['de'][364852] = {name = "[q5]Einigkeit", additional_info = "Runenschnitzmacht\n[q2]Gewährt einen legendären Effekt Eures auserwählten Pakts.\n[q]Runenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\n[q]Quelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n[q]Benötigt: Magier"}
MultiLanguageSpellData['de'][364853] = {name = "Harmonisches Echo", additional_info = "[q]Schaden, der mit der Verwundbarkeit von 'Strahlender Funke' belegten Gegnern zugefügt wird, hallt nach und fügt Eurem aktuellen gegnerischen Ziel sowie 4 Gegnern in der Nähe 25% des ursprünglichen Schadens zu."}
MultiLanguageSpellData['de'][364854] = {name = "Sündhafte Freuden", additional_info = "[q]Wenn Ihr [ Arkan : 'Freizaubern' ] [ Feuer : eine Aufladung von 'Feuerschlag' /\n\nFrost\n'Hirnfrost' ] verbraucht, wird die Abklingzeit von 'Spiegel der Qual' um 4 Sek. verringert. Wenn 'Spiegel der Qual' gebannt wird, wird die Abklingzeit um 45 Sek. verringert."}
MultiLanguageSpellData['de'][364855] = {name = "Tiefen des Todes", additional_info = "[q]Eure Zauber 'Feuerball', 'Frostblitz' und 'Arkanschlag' haben eine Chance, Euch für 8 Sek. 'Todesgeboren' zu gewähren. In der Gestalt eines Skelettmagiers wird der gewährte Zauberschaden für jeden von 'Feuerball', 'Frostblitz' und 'Arkanschlag' getroffenen Gegner um 1% erhöht."}
MultiLanguageSpellData['de'][364856] = {name = "Herz der Fae", additional_info = "[q]'Machtverschiebung' kann aus der Bewegung kanalisiert werden. Ihr erhaltet für jeden von 'Machtverschiebung' getroffenen Gegner 1% kritischen Trefferwert und Tempo, bis zu 10%. Hält 15 Sek. lang an."}
MultiLanguageSpellData['de'][364857] = {name = "[q5]Einigkeit", additional_info = "Runenschnitzmacht\n[q2]Gewährt einen legendären Effekt Eures auserwählten Pakts.\n[q]Runenschnitzen: Kopf, Hals, Schulter, Brust, Taille, Beine, Füße, Handgelenk, Hände, Finger, Rücken\n[q]Quelle: Ihr benötigt einen respektvollen Ruf bei den Erleuchteten und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können.\n[q]Benötigt: Mönch"}
MultiLanguageSpellData['de'][364858] = {name = "Ruf zu den Waffen", additional_info = "[q]'Waffen der Ordnung' ruft für 12 Sek. [ Braumeister : Niuzao, den Schwarzen Ochsen ] [ Nebelwirker : Chi-Ji, den Roten Kranich ] [ Windläufer : Xuen, den Weißen Tiger / Yu'lon, die Jadeschlange, ] zur Unterstützung an Eure Seite."}
MultiLanguageSpellData['de'][364859] = {name = "Finstere Lehren", additional_info = "[q]'Gefallener Orden' beschwört für 24 Sek. 1 zusätzlichen [Ochsen][Kranich][Tiger]adepten. Während Euer mystisches Portal geöffnet ist, verringern kritische Treffer mit Euren Fähigkeiten die Abklingzeit von 'Gefallener Orden' um [ Nebelwirker : 2.5 /\n\nBraumeister, Windläufer\n5 ] Sek."}
