MultiLanguageSpellData['de'][364861] = {name = "Faelinienharmonie", additional_info = "[q]Eure Fähigkeiten schließen die Abklingzeit von 'Faelinienstampfen' 100% häufiger ab. Durch 'Faelinienstampfen' getroffene Gegner und Verbündete werden mit 'Faekontakt' belegt, was Euren Schaden oder Eure Heilung bei ihnen 10 Sek. lang um 8% erhöht."}
