MultiLanguageSpellData['de'][367614] = {name = "[q4]Verbündetenhandgelenksschützer der Kameradschaft", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nTrophäenhalskette des Zentauren , Obsidianversengte Legierung (8), Funke (#247)\nOptionale Reagenzien:\nBeute von:\nAngriff der Zaqali\nZone:\nAberrus, Schmelztiegel der Schatten\nPläne:\nErhältlich im Auktionshaus\n\n[q4]Verbündetenhandgelenksschützer der Kameradschaft\nWird beim Aufheben gebunden\nHandgelenk Platte\n417 Rüstung\n+144 [Stärke oder Intelligenz]+234 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 111.\n[q2]Erhöht Eure Tempowertung um + 158.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Gewährt 25 Vielseitigkeit für jeden Verbündeten im Umkreis von 30 Metern. Bis zu 4-mal stapelbar.\n70"}
MultiLanguageSpellData['de'][367615] = {name = "[q4]Verbündetenbrustplatte des Großmuts", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nTrophäenhalskette des Zentauren , Obsidianversengte Legierung (10), Funke (#247)\nOptionale Reagenzien:\nBeute von:\nAngriff der Zaqali\nZone:\nAberrus, Schmelztiegel der Schatten\nPläne:\nErhältlich im Auktionshaus\n\n[q4]Verbündetenbrustplatte des Großmuts\nWird beim Aufheben gebunden\nBrust Platte\n834 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\n[q2]+ 171 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 307.\nHaltbarkeit 165 / 165\n[q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euch und Eure nächsten 4 Verbündeten innerhalb von 30 Metern für 10 Sek. in einen Siegesrausch zu versetzen, der die Vielseitigkeit um 138 erhöht.\n70"}
MultiLanguageSpellData['de'][367616] = {name = "[q4]Wutentbrannte Kriegsstiefel der Ungesühntheit", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nGroßer robuster Oberschenkelknochen (2), Obsidianversengte Legierung (2), Wutentbrannte Legierung (16), Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\n[q4]Wutentbrannte Kriegsstiefel der Ungesühntheit\nWird beim Aufheben gebunden\nFüße Platte\n521 Rüstung\n+193 [Stärke oder Intelligenz]+312 Ausdauer\n[q2]+ 256 Vielseitigkeit\n[q2]Erhöht Eure Meisterschaftswertung um + 102.\nHaltbarkeit 80 / 80\n[q2]Anlegen: Wenn Ihr einen Gegner erfolgreich mit einem Kontrollverlusteffekt belegt, ihn unterbrecht oder einen Effekt von einem Ziel bannt, wird Euer Primärwert 10 Sek. lang um 200 erhöht. Kann nur einmal alle 30 Sek. auftreten.\n70"}
MultiLanguageSpellData['de'][367617] = {name = "[q4]Wutentbrannter Helm der Rache", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nObsidianversengte Legierung (2), Wutentbrannte Legierung (20), Funke (#247)\nOptionale Reagenzien:\nVerkäufer:\nEraneth\nZone:\nValdrakken\nKosten:\n3\n\n[q4]Wutentbrannter Helm der Rache\nWird beim Aufheben gebunden\nKopf Platte\n625 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 184.\n[q2]+ 294 Vielseitigkeit\nHaltbarkeit 100 / 100\n[q2]Anlegen: Gegner, die Euch Schaden zufügen, erleiden manchmal [ 1982 * (2)] körperlichen Schaden im Verlauf von 6 Sek.\n70"}
MultiLanguageSpellData['de'][367618] = {name = "[q4]Instabiler Frostfeuergürtel", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nFrostige Seele , Feurige Seele , Frostfeuerlegierung (13), Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Azurblaues Gewölbe\nPläne:\nErhältlich im Auktionshaus\n\n[q4]Instabiler Frostfeuergürtel\nWird beim Aufheben gebunden\nTaille Platte\n469 Rüstung\n+193 [Stärke oder Intelligenz]+312 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 256.\n[q2]Erhöht Eure Meisterschaftswertung um + 102.\nHaltbarkeit 55 / 55\n[q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Gegner mit 'Verbleibender Frostfunke' zu belegen und ihnen [ 935 * (6)] Frostfeuerschaden im Verlauf von 10 Sek. zuzufügen. Gegner, die sterben, während dieser Effekt aktiv ist, explodieren und hinterlassen kalten Graupel, der 8 Sek. lang anhält und Gegner um 50% verlangsamt.\n70"}
MultiLanguageSpellData['de'][367619] = {name = "[q4]Frostfeuerbeinschützer der Vorbereitung", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nFrostige Seele , Feurige Seele , Frostfeuerlegierung (16), Funke (#247)\nOptionale Reagenzien:\nZone:\nAkademie von Algeth'ar und Azurblaues Gewölbe\nPläne:\nErhältlich im Auktionshaus\n\n[q4]Frostfeuerbeinschützer der Vorbereitung\nWird beim Aufheben gebunden\nBeine Platte\n729 Rüstung\n+257 [Stärke oder Intelligenz]+416 Ausdauer\n[q2]Erhöht Eure Tempowertung um + 212.\n[q2]Erhöht Eure Meisterschaftswertung um + 266.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Wenn Ihr einem neuen Gegner Schaden zufügt, wird Euer Tempo für 10 Sek. um 119 erhöht. Bis zu 5-mal stapelbar.\n70"}
MultiLanguageSpellData['de'][367620] = {name = "Korallenpirscherwellenrochen", additional_info = "Wirken in 1.5 sek.\n[q]Beschwört dieses Reittier oder gibt es wieder frei.\n[q]\"Diese Rochenart hat sich offensichtlich dazu entwickelt, mitten in bunten Korallenriffen auf ihre Beute zu lauern.\"\nPromotion"}
MultiLanguageSpellData['de'][367621] = {name = "Ermächtigter tückischer Stern", additional_info = "300 Meter Reichweite\nSofort\n[q]Anduin entsendet Wellen dunkler Energie, die sich nach außen bewegen und von den Rändern des Kampfbereichs abprallen. Getroffene Spielercharaktere erleiden alle 1 Sek. 34460 Zwielichtschaden und können nicht angreifen oder Zauber wirken. Hält 6 Sek. lang an.\n\n Wenn Anduins Diener von 'Tückischer Stern' getroffen werden, werden sie 10 Sek. lang alle 1 Sek. um 5% ihrer maximalen Gesundheit geheilt und sind währenddessen immun gegen Kontrollverlust- und Unterbrechungseffekte."}
MultiLanguageSpellData['de'][367622] = {name = "[q4]Urzeitlicher geschmolzener Verteidiger", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nUrzeitliche geschmolzene Legierung (15), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Sekundärwerte anpassen (#125) , Verzierung hinzufügen (#112) , Frischefluid (#124) , Glorreiche Einsicht (#93)\nSpezialisierung:\nRüstungsschmiedekunst - Schilde\n\n[q4]Urzeitlicher geschmolzener Verteidiger\nWird beim Aufheben gebunden\nSchildhand Schild\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n+208 Ausdauer\n[q2]+ 120 Zufallswert 1\n[q2]+ 120 Zufallswert 2\nHaltbarkeit 120 / 120\n70"}
MultiLanguageSpellData['de'][367623] = {name = "[q4]Schild des Herdfeuers", additional_info = "Wirken in 5 sek. 3\nTools: Schmiedehammer\nReagenzien:\nIrdene Seele , Leuchtende Titanenkugel , Urzeitliche geschmolzene Legierung (16), Funke (#247)\nOptionale Reagenzien:\nMit Energie erfüllen (#111) , Frischefluid (#124) , Glorreiche Einsicht (#93)\nSchatz:\nVersteckt auf den Dracheninseln\nPläne:\nErhältlich im Auktionshaus\n\n[q4]Schild des Herdfeuers\nWird beim Aufheben gebunden\nSchildhand Schild\n2442 Rüstung\n+128 Stärke\n+394 Intelligenz\n+208 Ausdauer\n[q2]Erhöht Eure kritische Trefferwertung um + 133.\n[q2]Erhöht Eure Meisterschaftswertung um + 106.\nHaltbarkeit 120 / 120\n[q2]Anlegen: Beim Erleiden von Schaden besteht die Chance, 239 Vielseitigkeit für 15 Sek. zu erhalten.\n70\n[q]\"Er erinnert Euch an Zuhause.\""}
