MultiLanguageSpellData['de'][367931] = {name = "Ketten der Herrschaft", additional_info = "15 Meter Reichweite\nSofort 3 min Abklingzeit\n[q]Rammt einen Stachel in Euer Ziel, der 5489 körperlichen Schaden verursacht und für 20 Sek. eine Kettenverbindung zwischen Euch schafft. Solange die Kette besteht, werden 25% des dem Ziel zugefügten Schadens in ihr gespeichert, bis zu maximal 2329 Schaden.\n\n Wenn Ihr Euch von Eurem Ziel entfernt, wird die Kette herausgerissen und die gespeicherte Schadensmenge wird allen Gegnern innerhalb von 8 Metern um das Ziel als Schattenschaden zugefügt."}
MultiLanguageSpellData['de'][367932] = {name = "Düsteres Schicksal", additional_info = "300 Meter Reichweite\nSofort\n[q]Wenn sie besiegt werden, ermächtigen düstere Reflexionen alle verbleibenden Reflexionen und erhöhen deren Tempo um 150%."}
MultiLanguageSpellData['de'][367937] = {name = "Resonante Wut", additional_info = "Wirken in 3 sek.\n[q]Wenn Pocopoc einen kernlosen Vombata übernimmt, hat er eine Chance, beim Töten einen Kampfrauscheffekt mit einer Dauer von 8 Sek. einzusetzen.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos."}
MultiLanguageSpellData['de'][367938] = {name = "Resonantes Gespinst", additional_info = "Wirken in 3 sek.\n[q]Wenn Pocopoc einen kernlosen Tarachniden übernimmt, gewährt Euch dies eine Chance, Nahkampfangreifer zu betäuben und zu vergiften.\nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos."}
MultiLanguageSpellData['de'][367939] = {name = "Resonanter Panzer", additional_info = "Wirken in 3 sek.\n[q]Wenn Pocopoc einen kernlosen Skarabiden übernimmt, verringert das Euren erlittenen Schaden um 10%. \nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos."}
MultiLanguageSpellData['de'][367940] = {name = "Resonanter Schleim", additional_info = "Wirken in 3 sek.\n[q]Wenn Pocopoc einen kernlosen Heliciden übernimmt, hat er eine Chance, bei Angriffen das Angriffs- und Zaubertempo des Gegners zu verringern. \nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos."}
MultiLanguageSpellData['de'][367941] = {name = "Resonantes Nachwachsen", additional_info = "Wirken in 3 sek.\n[q]Wenn Pocopoc einen kernlosen Geomentar übernimmt, baut er regelmäßig wiederherstellende Schilde um Euch auf. Der Schild zerspringt beim Erleiden von Schaden und stellt 5% Eurer maximalen Gesundheit wieder her. Bis zu 3-mal stapelbar. \nDieser Effekt dauert 15 Min. lang an. Funktioniert nur im Freien in den Schattenlanden oder in Oribos."}
