MultiLanguageSpellData['de'][367950] = {name = "Hoffnung des Löwen", additional_info = "Ca. 20 Procs pro Minute\n[q]Eure Zauber haben eine Chance, Hoffnung zu gewähren, was Euren Intelligenz für 12 Sek. um 17 erhöht. Ihr habt eine größere Chance, Hoffnung zu erhalten, wenn Ihr Verbündete oder Gegner mit niedriger Gesundheit als Ziel wählt."}
MultiLanguageSpellData['de'][367951] = {name = "Verzweiflung des Überrests", additional_info = "Ca. 20 Procs pro Minute\n[q]Eure Schaden verursachenden Zauber haben eine Chance, Eure Gegner mit Verzweiflung zu belegen, was den Effekt Eurer Krankheiten bei ihnen für 12 Sek. um 46 erhöht. Ihr habt eine größere Chance, Verzweiflung hervorzurufen, wenn Ihr Gegner mit höherer Gesundheit angreift."}
MultiLanguageSpellData['de'][367952] = {name = "Höchste Singularität", additional_info = "[q]Eure Offensivzauber bauen Stapel von 'Singularität' auf, was Euch pro Stapel 5 Vielseitigkeit und Geschwindigkeit gewährt, bis zu 20.\n\n Sobald Ihr 20 erreicht, werden diese Boni verdoppelt und halten 20 Sek. lang an. Nach Ablauf verliert Ihr alle Stapel und müsst 40 Sek. lang warten, bevor Ihr erneut 'Singularität' aufbauen könnt.\n(100ms Abklingzeit)"}
MultiLanguageSpellData['de'][367953] = {name = "Verdrehtes Richturteil", additional_info = "30 Meter Reichweite\nSofort 4 min Abklingzeit\n[q]Entfernt die Seele Eures Ziels, sodass das letzte Urteil über sie gefällt werden kann.\n\n Das Besiegen dieser Seele schickt sie in das Nachleben, das sie wirklich verdient, und gewährt Euch für 60 Sek. einen verdrehten Segen, der von ihrem jeweiligen Nachleben abhängt."}
