MultiLanguageSpellData['de'][368751] = {name = "Resonanzkaskade", additional_info = "500 Meter Reichweite\nSofort\n[q]Lihuvim erschafft eine kosmische Resonanz an der Position eines Spielercharakters, was allen Spielercharakteren innerhalb von 4 Metern um das Ziel 1044 kosmischen Schaden zufügt.\n\n Wenn dieser Zauber nicht sowohl melodische als auch harmonische Ausrichtungen trifft, entsteht stattdessen eine 'Dissonanzkaskade'."}
