MultiLanguageSpellData['de'][374486] = {name = "[q4]Götze der Lebensbinderin", additional_info = "Wirken in 2 sek. 3\nTools: Juwelierswerkzeuge\nReagenzien:\nFeurige Seele , Alexstraszit , Endlosdiamant , Glänzender Stein (10), Funke (#247)\nOptionale Reagenzien:\nPoliertuch (#182) , Glorreiche Einsicht (#93) , Mit Energie erfüllen (#111)\nVerkäufer:\nBoss Magor\nZone:\nKüste des Erwachens\nDrachenschuppenexpedition - Ruhmstufe 13\nKosten:\n200\n\nVerkäufer:\nKatalogisiererin Jakes\nZone:\nKüste des Erwachens\nDrachenschuppenexpedition - Ruhmstufe 13\nKosten:\n200\n\n[q4]Götze der Lebensbinderin\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)Schmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz][q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren kritischen Trefferwert pro ausgerüstetem Alexstraszit um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n[q]\"Morgen erwarten Euch neue Herausforderungen, und Ihr müsst bereit sein, ihnen gegenüberzutreten.\""}
MultiLanguageSpellData['de'][374487] = {name = "Fesselkette", additional_info = nil}
MultiLanguageSpellData['de'][374488] = {name = "[q4]Götze des Spruchwirkers", additional_info = "Wirken in 2 sek. 3\nTools: Juwelierswerkzeuge\nReagenzien:\nFrostige Seele , Malygit , Endlosdiamant , Glänzender Stein (10), Funke (#247)\nOptionale Reagenzien:\nPoliertuch (#182) , Glorreiche Einsicht (#93) , Mit Energie erfüllen (#111)\nVerkäufer:\nMurik\nZone:\nAzurblaues Gebirge\nKosten:\n400\n\nVerkäufer:\nRokkutuk\nZone:\nAzurblaues Gebirge\nKosten:\n400\n\n[q4]Götze des Spruchwirkers\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Götze der Aspekte (1)Schmuck\n+244 [Beweglichkeit oder Stärke oder Intelligenz][q2]Anlegen: Eure Zauber und Fähigkeiten haben eine Chance, Eure Vielseitigkeit pro ausgerüstetem Malygit um 34 zu erhöhen. Bei 18 Stapeln werden alle Stapel verbraucht und Eure Sekundärwerte werden 15 Sek. lang gleichmäßig um insgesamt 573 erhöht.\n[q]\"Ich habe in meiner Zeit viel verloren, sterbliches Wesen, eigentlich zu viel.\""}
