MultiLanguageSpellData['de'][377451] = {name = "Herbeigezauberte Frostkugel", additional_info = "40 Meter Reichweite\nSofort\n[q]Wenn Euer Mana über 65% ist, wird die Frostkugel auf Euer Ziel geworfen und verursacht 3041 Frostschaden.\n\n Wenn Euer Mana unter 65% ist, trinkt Ihr stattdessen von der Frostkugel, um sofort 562 Mana wiederherzustellen."}
MultiLanguageSpellData['de'][377452] = {name = "Flüsterndes Symbol der Inkarnation", additional_info = "[q]Gebt Euch dem Flüstern des Symbols hin und werdet mit Frost erfüllt, was Euren kritischen Trefferwert um 57 erhöht.\n\n Wenn Ihr an der Seite von Verbündeten kämpft, die mit Erde oder Feuer erfüllt sind, besteht eine Chance, dass Ihr 12 Sek. lang 16 des Werts ihrer jeweiligen Infusion erhaltet.\n\n Die Infusion ist von Eurer aktuellen Spezialisierung abhängig.\n(1.5s Abklingzeit)"}
MultiLanguageSpellData['de'][377453] = {name = "Segen der Sturmfresserin", additional_info = "Sofort 3 min Abklingzeit\n[q]Nehmt den Sturm an und werdet für 10 Sek. zu einem unbeweglichen Urluftelementar.\n\n In dieser Gestalt fügen die Winde um Euch allen Gegnern innerhalb von 10 Metern pro Sekunde 311 Naturschaden zu, der sich pro Sekunde um 10% erhöht, bis die Verwandlung endet."}
MultiLanguageSpellData['de'][377454] = {name = "Rasselnder Rubin", additional_info = "Ca. 5 Procs pro Minute\n[q]Eure Angriffe bauen langsam Stapel von 'Erschütternde Kraft' auf, die Euch pro Stapel 3 Angriffskraft gewähren.\n\n Bei 10 Stapeln entfesseln Eure nächsten 3 Nahkampffähigkeiten eine Schockwelle vor Euch, die allen Gegnern in einer Linie zusätzlich 903 Naturschaden zufügt. Die Schockwellen fügen Gegnern mit hoher Gesundheit mehr Schaden zu.\n(500ms Abklingzeit)"}
MultiLanguageSpellData['de'][377455] = {name = "Eisbluttodesfessel", additional_info = "45 Meter Reichweite\nSofort 2 min Abklingzeit\n[q]Fügt Eurem Ziel 2197 Frostschaden zu und wickelt es sowie Gegner in der Nähe für 15 Sek. in ein Kristallnetz. Im Netz gefangene Gegner sind um 15% verlangsamt und erleiden 174 Frostschaden, wenn ein Gegner im Netz getroffen wird.\n\n Der Schaden erhöht sich für jeden im Netz gefangenen Gegner, bis zu 5 Gegner. Der Schaden pro Ziel ist bei mehr als 5 Gegnern verringert."}
MultiLanguageSpellData['de'][377456] = {name = "Weg der kontrollierten Strömungen", additional_info = "[q]Eure kritischen Treffer haben eine Chance, 'Statische Elektrizität' aufzubauen, was Euer Angriffstempo pro Stapel um 2% erhöht. Dieser Effekt kann einmal alle 1 Sek. auftreten.\n\n Bei 10 Stapeln fährt ein Blitz durch Euch, der Eure Bewegungsgeschwindigkeit für 12 Sek. um 30% erhöht. Während Ihr vom Blitz ergriffen seid, schocken Eure automatischen Angriffe Euer Ziel und 1 weiteren Gegner in der Nähe und fügen ihnen 319 Naturschaden zu.\n\n Wenn dieser Effekt nachlässt, werdet Ihr für 1 Min. geerdet und könnt nicht erneut 'Statische Elektrizität' aufbauen.\n(1.5s Abklingzeit)"}
MultiLanguageSpellData['de'][377457] = {name = "Alltotem des Meisters", additional_info = "[q]Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\n Dieser Effekt kann nur einmal alle 30 Sek. auftreten.\n(30s Abklingzeit)"}
MultiLanguageSpellData['de'][377458] = {name = "Elementarhaltung: Erde", additional_info = "100 Meter Reichweite\nSofort\n[q]Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\n Dieser Effekt kann nur einmal alle 30 Sek. auftreten."}
MultiLanguageSpellData['de'][377459] = {name = "Elementarhaltung: Feuer", additional_info = "100 Meter Reichweite\nSofort\n[q]Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\n Dieser Effekt kann nur einmal alle 30 Sek. auftreten."}
MultiLanguageSpellData['de'][377461] = {name = "Elementarhaltung: Luft", additional_info = "100 Meter Reichweite\nSofort\n[q]Nehmt eine Elementarhaltung ein. Wenn Ihr einem Angriff erfolgreich ausweicht oder ihn pariert, entfesselt Ihr auf Gegner vor Euch einen mächtigen Elementargegenangriff, während Ihr die nächste Haltung einnehmt.\n\n Dieser Effekt kann nur einmal alle 30 Sek. auftreten."}
MultiLanguageSpellData['de'][377462] = {name = "Versprechen der Bruthüterin", additional_info = "100 Meter Reichweite\n{Wirken in} {1 sek. 5 sek. Abklingzeit}\n[q]Wählt einen Spielercharakter aus, mit dem Ihr eine Bindung eingehen möchtet, und werdet für 1 Stunde zu seinem Wächter.\n\n Während Ihr verbunden seid, erhaltet Ihr und Euer Verbündeter [ 11 * (0.8)] Vielseitigkeit und stellt pro Sekunde [ 45 * (0.6)] Gesundheit wieder her. Solange Ihr Euch innerhalb von 15 Metern zueinander aufhaltet, werden diese Boni erhöht.\n\nGilt nur für Heilerspezialisierungen."}
MultiLanguageSpellData['de'][377463] = {name = "Manische Trauerfackel", additional_info = "40 Meter ReichweiteKanalisiert (Wirken in 2 sek.) 2 min Abklingzeit\n[q]Kanalisiert für 2 Sek. und entfesselt eine wilde Salve aus Flammen um Euer Ziel herum, die ihm bis zu [ 951 * (8) * (1 + Vielseitigkeit)] Feuerschaden zufügt und eine Chance hat, zusätzlich Gegnern in der Nähe Schaden zuzufügen.\n\n Durch den Tod eines verbündeten Spielercharakters wird die Abklingzeit um 90 Sek. verringert."}
MultiLanguageSpellData['de'][377464] = {name = "Verzweifelte Herbeirufung", additional_info = "45 Meter Reichweite\nSofort 4 min Abklingzeit\n[q]Entfesselt gefährliche Blitze und fügt Eurem Ziel 5877 Naturschaden und Euch 31 Naturschaden zu. Der Euch selbst zugefügte Schaden wird durch Stapel von Hass erhöht."}
MultiLanguageSpellData['de'][377465] = {name = "Verzweifelte Herbeirufung", additional_info = "[q]Das Wirken von Zaubern gewährt Stapel von Hass, durch die die Abklingzeit dieses Schmuckstücks bis zum Ende des Kampfes um 1 Sek. verringert wird. Dieser Effekt ist bis zu 180-mal stapelbar.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][377466] = {name = "Boshafter Sturm", additional_info = "[q]Der Einsatz von Zaubern und Fähigkeiten erzeugt Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [ 86 * (6) * (1 + Vielseitigkeit)] Naturschaden.\n\n Bei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' zugefügten Schaden permanent, bis einer von Euch stirbt.\n(1s Abklingzeit)"}
MultiLanguageSpellData['de'][377467] = {name = "Fulminante Ladung", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Raszageth lädt Ziele mit Elektrizität auf3 Sek. lang bewegungsunfähig . Bei Ablauf entlädt sich die Aufladung, fügt allen Spielercharakteren im Effektbereich 88328 Naturschaden zu und springt auf den nächsten getroffenen Spielercharakter über.\n\n Jedes Mal, wenn ' Fulminante Ladung ' auf einen neuen Spielercharakter überspringt, verringert sich der Radius und der vorherige Spielercharakter wird mit ' Verbleibende Ladung ' belegt."}
