MultiLanguageSpellData['de'][382085] = {name = "Eidschwörer der Primalisten", additional_info = "Sofort\n[q]Legt den Primalisten gegenüber einen Schwur ab und erhaltet das Frostzeichen, wodurch sich Euer kritischer Trefferwert um eine [mittlere Menge] erhöht.\n\n Wenn Ihr an der Seite von Verbündeten kämpft, die über ein Erd- oder Feuerzeichen verfügen, besteht die Chance, dass Eure Statuswerte 12 Sek. lang um die Hälfte der Statuswerte ihrer jeweiligen Zeichen erhöht werden."}
