MultiLanguageSpellData['de'][382423] = {name = "Yusas herzhafter Eintopf", additional_info = "5 Meter Reichweite\nWirken in 1 sek.\n[q]Stellt einen frischen Topf mit Yusas herzhaftem Eintopf auf, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer niedrigster Sekundärwert wird 1 Stunde lang um 70 erhöht."}
MultiLanguageSpellData['de'][382424] = {name = "Schutz des Winters", additional_info = "[q]Verringert die Abklingzeit von 'Eisblock' um 30 Sek."}
MultiLanguageSpellData['de'][382425] = {name = "Bosheit", additional_info = "Sofort\n[q]Angriffe und Zauber erzeugen Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [wenig] Naturschaden.\n\n Bei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' verursachten Schaden permanent, bis einer von Euch stirbt."}
MultiLanguageSpellData['de'][382426] = {name = "Boshafter Sturmblitz", additional_info = "100 Meter Reichweite\nSofort\n[q]Angriffe und Zauber erzeugen Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [wenig] Naturschaden.\n\n Bei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' verursachten Schaden permanent, bis einer von Euch stirbt."}
MultiLanguageSpellData['de'][382427] = {name = "Großbankett der Kalu'ak", additional_info = "5 Meter Reichweite\nWirken in 1 sek.\n[q]Richtet für 3 Min. ein traditionelles Festmahl der Tuskarr aus, an dem sich alle Spielercharaktere satt essen können.\n\nStellt im Verlauf von 20 Sek. ( 45000 / 5 * 20) Gesundheit und ( 60000 / 5 * 20) Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und Euer Primärwert wird 1 Stunde lang um 76 erhöht."}
MultiLanguageSpellData['de'][382428] = {name = "Groll", additional_info = "100 Meter Reichweite\nSofort\n[q]Angriffe und Zauber erzeugen Stapel von Bosheit. Bei 5 Stapeln springt ein 'Boshafter Sturmblitz' auf Eurer anvisiertes Ziel über und verursacht im Verlauf von 3 Sek. [ 86 * (6) * (1 + Vielseitigkeit)] Naturschaden.\n\n Bei Ablauf kehrt der Blitz zurück, erhöht die benötigten Stapel von Bosheit um 1 und erhöht den dem Ziel durch 'Boshafter Sturmblitz' zugefügten Schaden permanent, bis einer von Euch stirbt."}
