MultiLanguageSpellData['de'][384688] = {name = "Drakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet."}
MultiLanguageSpellData['de'][384689] = {name = "Teilen und herrschen", additional_info = "[q][ Atem der Äonen : 'Atem der Äonen' / 'Tiefer Atem'] bildet Schleier aus Feuer, die Gegnern auf der anderen Seite die Sichtlinie blockieren und Gegnern, die sie durchqueren, verbrennen und so (480% der Zaubermacht) Feuerschaden zufügen. Hält 6 Sek. lang an."}
MultiLanguageSpellData['de'][384690] = {name = "Geschmolzenes Drakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\n Sie sind manchmal in Flammen gehüllt, besonders in seismisch aktiven Gebieten. Ihre unerträgliche Hitze hält Anfänger oft davon ab, ihr reiches Vorkommen an tobendem Feuer abzubauen.\n\n Die Spezialisierung auf geschmolzene Vorkommen gewährt beim Abbauen den folgenden Effekt:\n\n Glühender Zorn :\nHüllt Euch in Flammen und lässt Eure Angreifer 1721 Feuerschaden erleiden. Hält 2 Min. lang an."}
MultiLanguageSpellData['de'][384691] = {name = "Teilen und herrschen", additional_info = "100 Meter Reichweite\nSofort\n[q]'Tiefer Atem' bildet 8 Sek. lang eine Feuerwand, die die Sichtlinie blockiert. Gegner, die die Wand durchqueren, erleiden 1 Schaden."}
MultiLanguageSpellData['de'][384692] = {name = "Serevitvorkommen", additional_info = "5 Meter Reichweite\nWirken in 2.5 sek.\n[q]Serevit ist das am häufigsten zu findende Erz auf den Dracheninseln. Obwohl es oft in Gebirgsregionen vorkommt, wird es auch durch fließendes Wasser freigelegt.\nBeruf:\nBergbau (1)"}
MultiLanguageSpellData['de'][384693] = {name = "Reiches Drakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 5.3 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\n Reiche Vorkommen sind besonders ergiebig an Erzen und sicher eine Freude für jeden Bergarbeiter, der sie entdeckt."}
