MultiLanguageSpellData['de'][387614] = {name = "Gesang der Toten", additional_info = "10 Meter Reichweite\nWirken in 8 sek.\n[q]Fügt allen Spielercharakteren innerhalb von 10 Metern 4848899 Schattenschaden zu. Erhöht den verursachten Schaden aller untoten Verbündeten innerhalb von 10 Metern um 20% und verringert ihren erlittenen Schaden für 20 Sek. um 20%."}
MultiLanguageSpellData['de'][387615] = {name = "Griff der Toten", additional_info = "50 Meter Reichweite\nWirken in 3 sek.\n[q]Verringert die Bewegungsgeschwindigkeit des anvisierten Spielercharakters um 50% und fügt ihm 6 Sek. lang pro Sekunde 5 Schattenschaden zu.\n\n Nach 6 Sek. wird der Spielercharakter für 5 Sek. bewegungsunfähig."}
