MultiLanguageSpellData['de'][387617] = {name = "Segen der Pakte", additional_info = "Sofort\n[q]Ruft die Pakte der Schattenlande zu Hilfe, stellt (600% der Zaubermacht) Gesundheit wieder her und erhöht Eure Vielseitigkeit 12 Sek. lang um 10%.\n\nPassiv: Die Pakte haben Euch einen Teil ihrer Macht gewährt, was Euren Schaden und Eure Heilung um 4.0% erhöht."}
MultiLanguageSpellData['de'][387618] = {name = "Infusion", additional_info = "100 Meter Reichweite\nWirken in 5 sek.\n[q]Die Einflößerin der Primalisten kanalisiert auf den urtümlichen Tsunami und erhöht dessen verursachten Schaden um 1%. Dieser Effekt stapelt sich alle 5 Sek. weiter, bis er unterbrochen wird."}
