MultiLanguageSpellData['de'][388029] = {name = "Umgeleitete Essenz", additional_info = "200 Meter Reichweite\nSofort\n[q]Der instabile Infusor kanalisiert seine eigene Essenz auf Dathea und erhöht so 30 Sek. lang regelmäßig ihren verursachten Schaden um 10%. Dieser Effekt ist stapelbar."}
MultiLanguageSpellData['de'][388031] = {name = "Jadeband", additional_info = "[q]Euer 'Chikokon' wendet jetzt 4 Sek. lang 'Einhüllender Nebel' an, wenn er abläuft oder verbraucht wird. Die Heilung durch Chi-Jis 'Nebelschwall' ist um 20% erhöht, und die Heilung durch Yu'lons 'Beruhigender Atem' ist um 500% erhöht."}
MultiLanguageSpellData['de'][388033] = {name = "Gletscherstachel", additional_info = "20 Meter Reichweite\nSofort\n[q]Beschwört einen gewaltigen Eisstachel herbei, der Eure gesamten aktiven Eiszapfen in sich vereint. Er spießt Euer Ziel auf und verursacht (654% der Zaubermacht) Schaden sowie zusätzlich den gesamten in Euren Eiszapfen gespeicherten Schaden. Friert Euer Ziel außerdem 4 Sek. lang an Ort und Stelle fest. Dem Ziel zugefügter Schaden kann den Effekt unterbrechen.\n\n Zum Wirken werden 5 Eiszapfen benötigt.\n\nPassiv: 'Eislanze' lässt keine Eiszapfen mehr auf das Ziel niedergehen."}
MultiLanguageSpellData['de'][388034] = {name = "Blitzschlag", additional_info = "20 Meter Reichweite\nSofort\n[q]Schleudert einen Blitzschlag, der zu Gegnern in der Nähe überspringt und (40% der Zaubermacht) Natur schaden verursacht."}
MultiLanguageSpellData['de'][388035] = {name = "Zähigkeit des Bären", additional_info = "Unbegrenzte Reichweite\nSofort 2 min Abklingzeit\n[q]Erhöht Eure maximale Gesundheit sowie die Eures Begleiters für 10 Sek. um 20% und heilt Euch sofort um diesen Betrag."}
