MultiLanguageSpellData['de'][389406] = {name = "Titanversetztes Drakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\n Sie werden manchmal von kleinen Titanenforschungskonstrukten ermächtigt. Glücklicherweise tendieren sie dazu, ihre Stärkung dem zu gewähren, der das Vorkommen abbaut, statt sich zur Wehr zu setzen.\n\n Ihr erhaltet beim Abbauen den folgenden Effekt:\n\n Erleuchtetes Potenzial :\nErhöht die Geschwindigkeit um 15%. Außerdem werden die Sekundärwerte von auf titanenberührte Vorkommen spezialisierten Sammlern um 3% erhöht."}
MultiLanguageSpellData['de'][389407] = {name = "Wilde Rachfeder", additional_info = "Sofort\n[q]Eure Schadenszauber haben eine Chance, einen Seelensucherpfeil auf Euer Ziel zu verschießen, der dem ersten getroffenen Gegner 0 Schattenschaden im Verlauf von 1 Min. zufügt. Falls das Ziel stirbt, während es mit dem Effekt belegt ist, verschießen Eure nächsten Schadenszauber einen Pfeil."}
MultiLanguageSpellData['de'][389408] = {name = "Im'bunatas Zorn", additional_info = "Unbegrenzte Reichweite\n{Sofort} {10 sek. Abklingzeit}\n[q]Ruft den Zorn von Im'bunata herbei!"}
MultiLanguageSpellData['de'][389409] = {name = "Urdrakoniumvorkommen", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Drakoniumvorkommen sind ein seltener Fund auf den Dracheninseln, aber sie wurden öfter in rauen oder schwer zu erreichenden Umgebungen gesichtet.\n\n Sie sind manchmal von den Urelementen berührt und können zusätzliche tobende Elemente enthalten, die beim Abbauen entdeckt werden.\n\n Die Spezialisierung auf Urvorkommen gewährt beim Abbauen den folgenden Effekt:\n\n Explosive Elemente :\nErhöht die Abklingzeitverringerung von 'Überladung' um 30%. Spezialisierte Bergarbeiter haben eine Chance, mit ihren Zaubern und Fähigkeiten Bonuselementarschaden zu verursachen. Hält 2 Min. lang an."}
