MultiLanguageSpellData['de'][389710] = {name = "Ausbrennende Welle", additional_info = "100 Meter Reichweite\nSofort\n[q]Bindet Euch 20 Sek. lang an die Flamme, wodurch Eure Angriffe eine hohe Chance haben, Eure Stärke um 33 zu erhöhen. Bis zu 6-mal stapelbar. Wenn die Bindung vervollständigt wurde, sondert Ihr eine ausbrennende Welle ab, die abhängig von der Stärke Eurer Bindung bis zu 3775 Feuerschaden verursacht, der auf alle Gegner in der Nähe aufgeteilt wird."}
MultiLanguageSpellData['de'][389711] = {name = "Seelentreiber", additional_info = "[q]Wenn Ihr beim Verschlingen eines Seelenfragments über Eure volle Gesundheit hinaus geheilt werden würdet, erhaltet Ihr stattdessen einen Schild in Höhe von bis zu maximal (Gesamtgesundheit * 10 / 100)."}
