MultiLanguageSpellData['de'][391557] = {name = "Titanenberührtes Kraut überladen", additional_info = "5 Meter Reichweite\nWirken in 5.3 sek.\n[q]Die Überladung von Kräutern dieser Art bewirkt, dass sich ein Portal zu weiteren Kräutern in der Nähe öffnet. Spezialisierte Kräuterkundige können nach getaner Arbeit am Zielort ein Rückkehrportal öffnen."}
MultiLanguageSpellData['de'][391558] = {name = "Wutentbranntes Kraut überladen", additional_info = "5 Meter Reichweite\nWirken in 5.3 sek.\n[q]Die Überladung von Kräutern dieser Art verursacht eine verheerende Schockwelle, die Gegner in der Nähe zurückstößt und Euch selbst stärkt."}
MultiLanguageSpellData['de'][391559] = {name = "Schnellende Schüsse", additional_info = "[q]'Schnellfeuer' verursacht 35% mehr Schaden und 'Gezielter Schuss' hat eine Chance von 15%, die Abklingzeit von 'Schnellfeuer' abzuschließen.\n(Procchance: 15%)"}
MultiLanguageSpellData['de'][391560] = {name = "Windgepeitschtes Kraut überladen", additional_info = "5 Meter Reichweite\nWirken in 5.3 sek.\n[q]Die Überladung von Kräutern dieser Art verursacht eine massive Windböe, die Euch schnell in die Luft schleudert und es Euch ermöglicht, langsam zu Boden zu gleiten, während Ihr Kräuter und tobende Luft sammelt."}
