MultiLanguageSpellData['de'][393056] = {name = "Chiexplosion", additional_info = "Sofort\n[q]Wenn Ihr einem Ziel mit 'Furorfäuste' Schaden zufügt, erhaltet Ihr einen Stapel Chienergie, bis zu maximal 30 Stapel.\n\n Wenn Ihr 'Wirbelnder Kranichtritt' einsetzt, detoniert die Energie in einer 'Chiexplosion', die allen Gegnern innerhalb von 8 Metern (180% der Angriffskraft) Naturschaden zufügt. Fügt Zielen über 5 Ziele hinaus verringerten Schaden zu. Der Schaden erhöht sich pro Stapel Chienergie um 5%."}
MultiLanguageSpellData['de'][393057] = {name = "Chienergie", additional_info = "Sofort\n[q]Wenn Ihr einem Ziel mit 'Furorfäuste' Schaden zufügt, erhaltet Ihr einen Stapel Chienergie, bis zu maximal 30 Stapel.\n\n Wenn Ihr 'Wirbelnder Kranichtritt' einsetzt, detoniert die Energie in einer 'Chiexplosion', die allen Gegnern innerhalb von 8 Metern (65% der Angriffskraft) Schaden zufügt. Der Schaden erhöht sich pro Stapel Chienergie um 5%."}
MultiLanguageSpellData['de'][393058] = {name = "Xuens Band", additional_info = "Sofort\n[q]Der Schaden von 'Xuen den Weißen Tiger beschwören' ist um 30% erhöht und die Abklingzeit ist um 30 Sek. verringert."}
MultiLanguageSpellData['de'][393059] = {name = "Tausendbisspiranha", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Tausendbisspiranhas sind aggressive Süßwasserfische, die alles verschlingen, was ihnen in den Weg kommt!\n\n Diese Süßwasserschwärme findet man größtenteils in den großen Seen und weitverzweigten Flüssen der Dracheninseln.\n\n Besonders aktiv sind sie in Bereichen wie den Ebenen von Ohn'ahra und der Küste des Erwachens."}
MultiLanguageSpellData['de'][393060] = {name = "Himmelblauer Stachelfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Himmelblaue Stachelfische sind robuste stachelbedeckte Fische.\n\n Diese Salzwasserschwärme findet man gewöhnlich im Meer und damit verbundenen Gewässern.\n\n Besonders viele treiben sich in den Flussmündungen an der Küste des Erwachens herum."}
MultiLanguageSpellData['de'][393061] = {name = "Querflossen-Flügelrossfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Querflossen-Flügelrossfische gleiten den Meeresboden entlang und schnellen hinauf, sobald sie etwas Schmackhaftes dort oben erwarten!\n\n Diese Salzwasserschwärme findet man gewöhnlich im Meer und damit verbundenen Gewässern.\n\n Besonders viele treiben sich in Iskaara im Azurblauen Gebirge herum."}
MultiLanguageSpellData['de'][393062] = {name = "Temporaler Drachenkopf", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Temporale Drachenköpfe sind merkwürdige Fische, deren Schuppen so wirken, als würden sie alle paar Sekunden ein wenig vor und zurück versetzt. Finger weg vom scharfen Maul!\n\n Diese Süßwasserschwärme findet man größtenteils in den großen Seen und weitverzweigten Flüssen der Dracheninseln.\n\n Besonders viele treiben sich im Uktulutaltwasser der Küste des Erwachens herum."}
MultiLanguageSpellData['de'][393063] = {name = "Schuppenbauchmakrele", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Schuppenbauchmakrelen sind äußerst gewöhnliche Fische auf den Dracheninseln. Man kann sie überall leicht fangen.\n\n Selbst erfahrene Angler werfen sie regelmäßig zurück ins Wasser."}
MultiLanguageSpellData['de'][393064] = {name = "Inselfinnenschwertfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Inselfinnenschwertfische sind scheue Wesen, deren Finne angeblich der Form der Dracheninseln ähnelt.\n\n Man findet sie überall auf den Inseln."}
MultiLanguageSpellData['de'][393065] = {name = "Schimmernder Schatz", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Schimmernde Schatzbecken findet man in allen Gewässern der Dracheninseln. Diese Becken enthalten unermessliche Schätze und ein jeder Angler erhofft, sie zu entdecken.\n\n Angeln in diesen Becken erhöht die Chance auf seltene Schätze erheblich."}
MultiLanguageSpellData['de'][393066] = {name = "Raureifflossenthunfisch", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Raureifflossenthunfische sind große, fetthaltige Fische, die von einer dünnen Schutzschicht aus Eis umgeben sind. Die dicke Fettschicht schützt ihre Organe vor den eisigen Temperaturen.\n\n Ihr findet diese Schwärme in besonders frostigen Bereichen der Dracheninseln.\n\n Die Tuskarr von Iskaara sind Experten, was den Fang dieser Fische betrifft."}
MultiLanguageSpellData['de'][393067] = {name = "Magmadrescher", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Magmadrescher sind muskulöse Fische mit einer verhärteten Hülle aus verschiedenen Mineralien.\n\n Ihr findet diese Schwärme in besonders heißen Bereichen der Dracheninseln.\n\n Die Tuskarr von Iskaara sind Experten im Fang dieser besonderen Fischart."}
MultiLanguageSpellData['de'][393068] = {name = "Prismatischer Springer", additional_info = "5 Meter Reichweite\nWirken in 3.2 sek.\n[q]Prismatische Springer sind neugierige bewegliche Fische, deren Schuppen im Licht schimmern.\n\n Diese Fische lieben es, aus dem Wasser zu springen, und man findet sie an einigen der höchsten Punkte auf den Dracheninseln.\n\n Die Tuskarr von Iskaara sind Experten im Fang dieser besonderen Fischart."}
MultiLanguageSpellData['de'][393070] = {name = "New Class Order", additional_info = nil}
