MultiLanguageSpellData['de'][393073] = {name = "PvP-Ausrüstung aufwerten", additional_info = "Wirken in 3 sek.\n[q]Wertet einen Teil Ehren- oder Eroberungsausrüstung aus Saison 1 von Dragonflight auf den nächsten Rang auf.\n\n Gegenstände können nicht den Rang überschreiten, den Euer höchster Rang im gewerteten PvP erlaubt."}
