MultiLanguageSpellData['de'][394324] = {name = "Tödliches Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Schlag besteht eine Chance von 30%, den Gegner zu vergiften. Das Gift verursacht im Verlauf von 12 Sek. [(11.374% der Angriffskraft) * 12 / 2] Naturschaden. Weitere Anwendungen auf das Ziel während der Effektdauer verursachen sofort (8.14% der Angriffskraft) Naturschaden."}
MultiLanguageSpellData['de'][394325] = {name = "Tödliches Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Wenn Eure Waffen vergiftet sind, besteht eine Chance, dass Ihr Zielen, die bereits mit Eurem tödlichen Gift vergiftet sind, (8.14% der Angriffskraft) Naturschaden zufügt."}
MultiLanguageSpellData['de'][394326] = {name = "Sofort wirkendes Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (7.4% der Angriffskraft) Naturschaden verursacht."}
MultiLanguageSpellData['de'][394327] = {name = "Wundgift", additional_info = "100 Meter Reichweite\nSofort\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was sofort (4.07% der Angriffskraft) Naturschaden verursacht und 12 Sek. lang sämtliche erhaltene Heilung um 8% verringert. Dieser Effekt ist bis zu 3-mal stapelbar."}
MultiLanguageSpellData['de'][394328] = {name = "Verstärkendes Gift", additional_info = "100 Meter Reichweite\nSofort\n[q]Überzieht Eure Waffen mit einem tödlichen Gift, das 1 Stunde lang an ihnen haften bleibt. Bei jedem Angriff besteht eine Chance von 30%, den Gegner zu vergiften, was ihm (8.14% der Angriffskraft) Naturschaden zufügt und ihn für 12 Sek. mit 'Verstärkendes Gift' belegt. 'Vergiften' kann 10 Stapel 'Verstärkendes Gift' verbrauchen, um 35% mehr Schaden zu verursachen. Maximal 20 Stapel."}
