MultiLanguageSpellData['de'][396363] = {name = "Donnernd", additional_info = "Sofort\n[q]Raszageth markiert einen Spielercharakter mit einem ' Mal des Windes ' oder ' Mal des Blitzes ', wodurch dessen verursachter Schaden und hervorgerufene Heilung 15 Sek. lang um 30% erhöht wird. Mit dem gegensätzlichen Mal in Kontakt zu kommen, neutralisiert den Effekt für beide Spielercharaktere.\n\n Nach 15 Sek. erleiden die betroffenen Spielercharaktere eine ' Urzeitliche Überladung ', wodurch sie betäubt werden und 5 Sek. lang alle 1 Sek. 9 Naturschaden erleiden."}
MultiLanguageSpellData['de'][396364] = {name = "Mal des Windes", additional_info = "Unbegrenzte Reichweite\nSofort\n[q]Erfüllt einen Spielercharakter mit urzeitlicher Kraft und erhöht dessen Schaden und Heilung 15 Sek. lang um 30%.\n\n Wenn sich bei Ablauf innerhalb von 100 Metern ein Spielercharakter mit ' Mal des Blitzes ' befindet, wird ' Urzeitliche Überladung ' ausgelöst, betäubt die markierten Spielercharaktere für 5 Sek. und fügt ihnen währenddessen alle 1 Sek. 9 Naturschaden zu.\n\n Dieser Effekt wird bei Kontakt mit einem ' Mal des Blitzes ' entfernt."}
